import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SensorService, SensorData, DashboardStats } from '../../Services/sensor.service';
import { AuthService } from '../../Services/auth.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  stats: DashboardStats | null = null;
  sensorHistory: SensorData[] = [];

  filterType: string = 'All';
  filterSensorId: string = '';

  isLoading: boolean = false;

  constructor(
    private sensorService: SensorService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadStats();
    this.loadHistory();
  }

  loadStats(): void {
    this.sensorService.getStats().subscribe({
      next: (data) => {
        // Parse weather values for the stats view
        data.latestReadings.forEach(item => {
          if (item.type === 'weather') {
            try {
              item.parsedValue = JSON.parse(item.value);
            } catch {
              item.parsedValue = item.value;
            }
          }
        });
        this.stats = data;
      }
    });
  }

  loadHistory(): void {
    this.isLoading = true;
    this.sensorService.getHistory(this.filterType, this.filterSensorId).subscribe({
      next: (data) => {
        this.sensorHistory = data.map(item => {
          // Attempt to parse JSON values (like weather)
          if (item.value.trim().startsWith('{')) {
            try {
              return { ...item, parsedValue: JSON.parse(item.value) };
            } catch {
              return { ...item, parsedValue: item.value };
            }
          }
          return { ...item, parsedValue: item.value };
        });
        this.isLoading = false;
      },
      error: () => this.isLoading = false
    });
  }

  applyFilters(): void {
    this.loadHistory();
  }

  logout(): void {
    this.authService.logout();
    this.router.navigate(['/login']);
  }

  getWeatherIcon(temp: number): string {
    if (temp > 30) return '☀️'; // Hot
    if (temp < 10) return '❄️'; // Cold
    return 'Tm'; // Normal
  }
}
